<script setup lang="ts">
import {ref,watch,nextTick,onUnmounted} from 'vue';
type Summary={projects:number;tasks:number;duplicate_projects:number;duplicate_tasks:number;create_projects:number;create_tasks:number;seconds:number;samples:string[]};
const props=defineProps<{csrf:string;disabled:boolean}>();
const emit=defineEmits<{working:[boolean];changed:[]}>();
const opened=ref(false),busy=ref(false),error=ref(''),success=ref(''),payload=ref(''),fileName=ref(''),strategy=ref('skip'),fingerprint=ref(''),summary=ref<Summary|null>(null),requestKey=ref('');
watch(strategy,()=>{summary.value=null;fingerprint.value='';requestKey.value='';success.value=''});
async function api(url:string,body:unknown){const r=await fetch(url,{method:'POST',credentials:'same-origin',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':props.csrf},body:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw Error(d.errors?Object.values(d.errors).flat().join(' '):d.message||'Не удалось выполнить запрос');return d;}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;emit('working',true);error.value='';success.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:'Ошибка соединения'}finally{busy.value=false;emit('working',false)}}
function open(){if(props.disabled)return;opened.value=true;nextTick(()=>document.querySelector<HTMLButtonElement>('.transfer-modal button')?.focus())}
function close(){if(busy.value)return;opened.value=false;nextTick(()=>document.querySelector<HTMLButtonElement>('.transfer-button')?.focus())}
function file(event:Event){const f=(event.target as HTMLInputElement).files?.[0];payload.value='';summary.value=null;fingerprint.value='';requestKey.value='';fileName.value=f?.name||'';if(!f)return;run(async()=>{if(f.size>5*1024*1024)throw Error('Максимальный размер файла — 5 МБ.');payload.value=await f.text()})}
function preview(){run(async()=>{const d=await api('/transfer/preview',{payload:payload.value,strategy:strategy.value});summary.value=d.summary;fingerprint.value=d.fingerprint;requestKey.value=crypto.randomUUID()})}
function confirm(){if(!summary.value)return;run(async()=>{const d=await api('/transfer/import',{payload:payload.value,strategy:strategy.value,fingerprint:fingerprint.value,request_key:requestKey.value});success.value=`Импорт завершён: проектов создано ${d.created_projects}, задач создано ${d.created_tasks}, задач пропущено ${d.skipped_tasks}.`;summary.value=null;fingerprint.value='';emit('changed')})}
function download(){run(async()=>{const r=await fetch('/transfer/export',{credentials:'same-origin',headers:{Accept:'application/json'}});if(!r.ok){const d=await r.json();throw Error(d.errors?Object.values(d.errors).flat().join(' '):d.message||'Не удалось выгрузить данные')}const blob=await r.blob();const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=r.headers.get('Content-Disposition')?.match(/filename="([^"]+)"/)?.[1]||'sovdelo-export.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);success.value='JSON подготовлен для скачивания.'})}
function beforeUnload(e:BeforeUnloadEvent){if(busy.value){e.preventDefault();e.returnValue=''}}
window.addEventListener('beforeunload',beforeUnload);onUnmounted(()=>window.removeEventListener('beforeunload',beforeUnload));
function key(e:KeyboardEvent){if(e.key==='Escape'){e.stopPropagation();close()}if(e.key==='Tab'){const nodes=Array.from(document.querySelectorAll<HTMLElement>('.transfer-modal button:not(:disabled),.transfer-modal input:not(:disabled),.transfer-modal select:not(:disabled)')).filter(n=>!n.closest('fieldset:disabled'));const a=nodes[0],b=nodes.at(-1);if(e.shiftKey&&document.activeElement===a){e.preventDefault();b?.focus()}else if(!e.shiftKey&&document.activeElement===b){e.preventDefault();a?.focus()}}}
</script>
<template>
 <button class="transfer-button" :disabled="disabled" @click="open">Импорт / экспорт</button>
 <div v-if="opened" class="overlay transfer-overlay" @click.self="close" @keydown="key"><section class="modal transfer-modal" role="dialog" aria-modal="true" aria-labelledby="transfer-title">
 <div class="detail-head"><h2 id="transfer-title">Импорт и экспорт</h2><button :disabled="busy" aria-label="Закрыть перенос данных" @click="close">×</button></div>
 <p v-if="error" class="error" role="alert">{{error}}</p><p v-if="success" class="save-status" role="status">{{success}}</p>
 <fieldset :disabled="busy"><h3>Экспорт в JSON</h3><p class="muted">Проекты, задачи, архив и корзина, чек-листы, метки, комментарии и история времени. Активное время попадёт в файл завершённым снимком; текущий таймер продолжит работать.</p><p class="muted">Без файлов, расписаний повторов, напоминаний и настроек аккаунта. Это перенос данных, а не полная резервная копия.</p><button class="primary" @click="download">Скачать JSON</button>
 <h3>Импорт</h3><label>Файл СовДело · до 5 МБ<input type="file" accept=".json,application/json" @change="file"></label><p v-if="fileName" class="muted">{{fileName}}</p><label>Если данные уже есть<select v-model="strategy"><option value="skip">Пропустить существующие</option><option value="copy">Создать отдельные копии</option></select></label><p class="muted">Совпадение определяется идентификатором из экспорта, включая архив и корзину. Название само по себе не делает задачу дублем. Существующие задачи и проекты не изменяются. Если совпавший проект в архиве, добавленные в него задачи останутся в архиве проекта. Метки с одинаковым именем используются повторно.</p><button :disabled="!payload" @click="preview">Проверить файл</button>
 <section v-if="summary" class="transfer-preview"><h3>Предварительный просмотр</h3><dl><dt>В файле</dt><dd>{{summary.projects}} проектов · {{summary.tasks}} задач</dd><dt>Уже существуют</dt><dd>{{summary.duplicate_projects}} проектов · {{summary.duplicate_tasks}} задач</dd><dt>Будет создано</dt><dd>{{summary.create_projects}} проектов · {{summary.create_tasks}} задач</dd><dt>Время во всём файле</dt><dd>{{(summary.seconds/3600).toFixed(2)}} ч</dd></dl><ul><li v-for="(title,i) in summary.samples" :key="i">{{title}}</li></ul><p class="muted">Импорт сохранит архив и корзину. Таймеры, повторы и напоминания не запускаются. Если данные изменились после проверки, количество будет пересчитано при импорте.</p><button class="primary" @click="confirm">Подтвердить импорт</button></section>
 </fieldset><p v-if="busy" role="status">Обрабатываем данные…</p>
 </section></div>
</template>
